/**
 * Registers a paper wallet generated by an operator, on the holder's behalf.
 *
 * The operator's browser holds the fresh key, so it can sign the holder's own
 * SIWE signup — the backend sees an ordinary self-registration, which it
 * approves on creation. What makes this different from web onboarding is that
 * the operator is signed in: the signup is `detached` so its session cookie is
 * discarded rather than replacing the operator's, and anything signup cannot
 * carry (phone, country, currency) is written afterwards through the admin
 * profile endpoint, under the operator's session.
 *
 * On-chain activation is not done here. apps/web attaches the EIP-7702
 * authorization to a wallet's first relayed transaction, so a card that is
 * never used costs the relayer nothing.
 */

import type { PaperWalletRecipient } from "@clc/core/features/paper-wallet-batch/logic";
import {
  PAPER_WALLET_PLACEHOLDER_NAME,
  placeholderSignupEmail,
} from "@clc/core/features/wallet/paper-wallet";

import { BackendApiError } from "../../client/errors";
import type { AdminClient } from "../admin/client";
import type { AuthClient } from "../auth/client";
import { privateKeySigner, signSiweMessage, type SiweRequest } from "../auth/siwe";

export type ProvisionPaperWalletInput = {
  auth: AuthClient;
  admin: AdminClient;
  privateKey: `0x${string}`;
  recipient: PaperWalletRecipient;
  siwe: SiweRequest;
};

export type ProvisionedPaperWallet = {
  address: `0x${string}`;
  /**
   * Set when the account exists but the phone, country or currency could not be
   * saved. The wallet is still usable and printable; the holder can add the
   * missing details themselves.
   */
  profileError?: string;
};

export async function provisionPaperWallet({
  auth,
  admin,
  privateKey,
  recipient,
  siwe,
}: ProvisionPaperWalletInput): Promise<ProvisionedPaperWallet> {
  const signer = privateKeySigner(privateKey);
  const name = recipient.name.trim() || PAPER_WALLET_PLACEHOLDER_NAME;
  const email = recipient.email.trim() || placeholderSignupEmail(signer.address);

  // A 409 for this address means a previous attempt registered it and its
  // response was lost; `signupWithSiwe` reports that rather than throwing, so a
  // retry carries on to the profile step.
  await auth.signupWithSiwe(
    { ...(await signSiweMessage(auth, signer, siwe)), name, email },
    { detached: true },
  );

  if (!recipient.phone && !recipient.country && !recipient.currency) {
    return { address: signer.address };
  }

  try {
    await admin.updateUserProfile(signer.address, {
      name,
      email,
      phone: recipient.phone,
      country: recipient.country,
      ...(recipient.currency ? { preferredCurrency: recipient.currency } : {}),
    });
    return { address: signer.address };
  } catch (error) {
    return { address: signer.address, profileError: describeProvisionError(error) };
  }
}

/** Operator-facing reason for a failed step, naming the field when the backend does. */
export function describeProvisionError(error: unknown): string {
  if (error instanceof BackendApiError) {
    if (error.code === "E17") return "Email already belongs to another account";
    if (error.code === "E18") return "Phone number already belongs to another account";
    return error.message;
  }
  return error instanceof Error ? error.message : "Unknown error";
}
